"""Write transparent reports for conditional normalization and native feature repair."""
import json,datetime,hashlib
from pathlib import Path
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
ROOT=Path(__file__).resolve().parents[1]
def read(p):return json.loads(p.read_text(encoding='utf-8'))
def table_row(name,r):
 c=r['classification_report'];d=c['disgust'];return f"| {name} | {r['accuracy']:.2%} | {c['macro avg']['f1-score']:.4f} | {d['precision']:.4f}/{d['recall']:.2%}/{d['f1-score']:.4f} | {c['happy']['recall']:.2%} | {c['surprise']['recall']:.2%} | {c['neutral']['recall']:.2%} |"
def finish(lines,run,output):
 decision=read(run/'deployment_decision.json');lines+=['','## Test and deployment decision','',decision['reason'],'',f"New test evaluated: {decision['test_evaluated']}. Eligible: {decision['eligible']}. All prospective accuracy/macroF1, macroP/R, disgustP/R/F1 and historical happy/surprise/neutral recovery floors remain unchanged. No alternate model is tested after a test failure."]
 if decision['test_evaluated']:
  result=read(run/'deployment/reports/emotion_evaluation.json');base=read(run/'current_test.json');lines+=['',f"All{result['n']} retained test faces; this is the historically inspected fixed cohort, not fresh identity-disjoint confirmation.",'',table_row('Current PURE full TEST',base),table_row('Frozen PURE full TEST',result),'','| Class | Current test recall | Candidate test recall | Difference (percentage points) |','|---|---:|---:|---:|']
  for name in ['angry','disgust','fear','happy','sad','surprise','neutral']:
   a=base['classification_report'][name]['recall'];b=result['classification_report'][name]['recall'];lines.append(f'| {name} | {a:.2%} | {b:.2%} | {(b-a)*100:+.2f} |')
 else:lines+=['', 'No new test result is claimed. The deployed pure result remains58.34% accuracy,0.5554macroF1,46.84%disgust recall. No app or PPT replacement is justified by this phase.']
 protected={n:hashlib.sha256((ROOT/n).read_bytes()).hexdigest()==h for n,h in read(run/'protected_artifacts.json').items()};lines+=['',f'Protected app/model/PPT files all unchanged before any integration: {all(protected.values())}.','', 'All classes, faces and errors remain included. No uncertainty-based filtering, post-test thresholds, external encoder or probability mixture is used. TRAIN/validation/test cohorts are fixed. This is exploratory engineering with repeated validation use and historical test inspection, not clinical or webcam-domain confirmation. EEG/HRV/weather/raga-efficacy results are unchanged. No user photograph or real sensor was used.']
 audit=run/'fixed_checkpoint_generalization_audit.json'
 if audit.exists():
  a=read(audit);lines+=['','## Fixed-checkpoint overfitting audit','',f"All23503original TRAIN faces, eval mode, no augmentation/dropout: baseline TRAINaccuracy {a['baseline_train']['accuracy']:.2%}, validation {a['baseline_validation']['accuracy']:.2%}, gap {a['accuracy_gap_before']:.2%}; candidate TRAINaccuracy {a['candidate_train']['accuracy']:.2%}, validation {a['candidate_validation']['accuracy']:.2%}, gap {a['accuracy_gap_after']:.2%}. These are comparable fixed-checkpoint measurements, not epoch-running augmented training accuracy. A smaller gap alone is not a successful improvement."]
 (ROOT/output).write_text('\n'.join(lines)+'\n',encoding='utf-8');(run/'report_audit.json').write_text(json.dumps({'report':output,'protected_unchanged':protected,'decision':decision},indent=2),encoding='utf-8');print(output)
def main():
 bn=ROOT/'reports/pure_capacity_bn_20261108';res=ROOT/'reports/pure_residual_capacity_20261108';header=['| Model/stage | Accuracy | Macro F1 | Disgust P/R/F1 | Happy recall | Surprise recall | Neutral recall |','|---|---:|---:|---|---:|---:|---:|'];now=datetime.datetime.now().astimezone().isoformat()
 if (bn/'deployment_decision.json').exists():
  lines=['# TRAIN-only pure FusDenseNet BatchNorm check','',now,'', 'Three fixed candidates: current pure baseline, final compact student and final compact averaged network. Each receives one pass over all23503unaugmented TRAIN images. Labels are ignored and every learned parameter remains bit-identical; only native BatchNorm running buffers change. No validation/test image contributes to these statistics.','', 'This uses the installed PyTorch2.5.1 update_bn implementation, inspected locally, consistent with [official PyTorch documentation](https://docs.pytorch.org/docs/2.15/optim.html#taking-care-of-batch-normalization). The drift audit on1024TRAINfaces found modest average mean shifts0.0514storedSD for the original and0.0578for the fine-tuned model; this does not establish a major BatchNorm defect or cause of overfitting.','', 'All validation results below use3970real faces, including50disgust examples. High disgust recall with collapsed precision is rejected.','']+header+[table_row('Current PURE validation',read(bn/'current_validation.json'))]
  for entry in read(bn/'validation_comparisons.json'):lines.append(table_row(entry['candidate'],read(bn/entry['candidate']/'validation.json')))
  lines+=['', 'Two normalization contract tests passed in8.53seconds. All original raw/EMA/source models and buffer audits are retained; no rejected model replaces the app.']
  finish(lines,bn,'PURE_BATCHNORM_RESULTS.md')
 if (res/'deployment_decision.json').exists():
  history=read(res/'full_history.json');initialization=read(res/'zero_initialization_preflight.json');lines=['# Compact native residual FusDenseNet results','',now,'',f"Completed{len(history)}additional full-network epochs. This phase ran only after the earlier compact6-epoch phase and all three BN checks produced no eligible/tested candidate. No earlier new test was opened.",'', 'Version11 keeps the original native FusDenseNet stem, three fusion-dense stages, cross-dense connections, attention and global/coarse pooling. It adds zero-output native residual dense refinements in each fusion branch, using two dilated dense growth layers, GroupNorm and local1x1feature fusion. The compact1260-to256-to7classifier is retained. This is a disclosed project extension, not an exact recovered author topology. No external encoder, teacher from another architecture or probability ensemble is used.','',f"Total parameters{initialization['parameters']:,};117,360new feature parameters. Initial predictions matched the final compact source on64real validation faces with maximum logit discrepancy{initialization['maximum_logit_error']}. Three new tests passed in21.81seconds: exact initial-function preservation, gradients reaching new residual filters, and portable checkpoint loading.",'', 'The normalization component follows [Wu and He, Group Normalization (2018)](https://arxiv.org/abs/1803.08494); their published results are not project results.','', 'New feature modules use LR1e-4, retained native feature parameters1e-5, classifier3e-5; mild TRAIN image augmentation, dropout.5,smoothing.025 and same-current-pure TRAIN disgust-boundary retention. TRAIN class-cost multipliers: happy1.25,surprise1.25,neutral1.0. This addresses excessive neutral allocation seen in the compact phase through supervised training costs, not inference offsets. The joint architecture/loss/optimizer change is not a causal ablation.','', 'Earlier279classifier trial epochs were independent recipes, including one timing-limited one-epoch recipe. The accepted source lineage contains only its selected classifier warm-up, the6compact full-network passes and these additional native refinement passes. Full/head epochs are not equivalent compute. No failed BN-recalibrated weights initialize this phase.','', 'All validation rows use the same3970real faces. Student and averaged models are separately evaluated; each is a single pure network, not an inference mixture.','']+header+[table_row('Current PURE validation',read(res/'current_validation.json'))]
  for i in range(1,len(history)+1):
   for kind in ['student','EMA']:lines.append(table_row(f'Native refinement epoch{i} {kind}',read(res/f'full_validation_{i:02d}_{kind}.json')))
  finish(lines,res,'PURE_RESIDUAL_CAPACITY_RESULTS.md')
  fig,axes=plt.subplots(2,3,figsize=(16,8));keys=['val_accuracy','val_macro_f1','val_disgust_recall','val_happy_recall','val_surprise_recall','val_neutral_recall'];base=read(res/'current_validation.json');c=base['classification_report'];baseline=[base['accuracy'],c['macro avg']['f1-score'],c['disgust']['recall'],c['happy']['recall'],c['surprise']['recall'],c['neutral']['recall']]
  for ax,key,b in zip(axes.flat,keys,baseline):
   ax.plot(range(1,len(history)+1),[r[key] for r in history],marker='o');ax.axhline(b,color='black',linestyle='--');ax.set(title=key.replace('_',' '),xlabel='Additional native refinement epoch');ax.set_xticks(range(1,len(history)+1));ax.grid(alpha=.2)
  fig.suptitle('Actual real-image validation: native residual FusDenseNet, not test results');fig.tight_layout();fig.savefig(res/'residual_validation_curves.png',dpi=140);plt.close(fig)
if __name__=='__main__':main()
